<?php require 'includes/config.php';if(!user())redirect('login.php?next=checkout.php');$rows=cart_rows();if(!$rows)redirect('cart.php');$delivery=350;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'');$method=$_POST['payment']??'';if(!$name||!preg_match('/^[0-9+() -]{9,20}$/',$phone)||!$address||!$city||!in_array($method,['cod','bank'],true))$error='Please complete all fields and choose a supported payment method.';else{try{$pdo=db();$pdo->beginTransaction();$locked=[];$total=0;foreach($rows as $r){$s=$pdo->prepare('SELECT id,name,price,stock FROM products WHERE id=? FOR UPDATE');$s->execute([$r['id']]);$v=$s->fetch();if(!$v||$v['stock']<$r['qty'])throw new Exception('Some items are no longer available in the requested quantity.');$locked[]=[$v,$r['qty']];$total+=$v['price']*$r['qty'];}$s=$pdo->prepare('INSERT INTO orders(user_id,customer_name,phone,address,city,payment_method,total,status) VALUES(?,?,?,?,?,?,?,?)');$s->execute([user()['id'],$name,$phone,$address,$city,$method,$total+$delivery,'pending']);$orderId=$pdo->lastInsertId();foreach($locked as [$v,$qty]){$s=$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');$s->execute([$orderId,$v['id'],$qty,$v['price']]);$s=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');$s->execute([$qty,$v['id']]);}$pdo->commit();unset($_SESSION['cart']);redirect('success.php?id='.$orderId);}catch(Throwable $ex){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$ex instanceof PDOException?'Could not place order. Please try again.':$ex->getMessage();}}}$pageTitle='Checkout';require 'includes/header.php';?><section class="container section-space"><div class="eyebrow">SECURE ORDER FORM</div><h1 class="page-title">Your <em>Checkout</em></h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="row g-4 mt-3"><div class="col-lg-7"><form id="checkout" method="post" class="filter-panel"><input type="hidden" name="csrf" value="<?=csrf()?>"><h4>Delivery Details</h4><label class="form-label mt-3">Full Name</label><input name="name" class="form-control" required value="<?=e($_POST['name']??user()['name'])?>"><label class="form-label mt-3">Phone Number</label><input name="phone" class="form-control" required value="<?=e($_POST['phone']??'')?>"><label class="form-label mt-3">Street Address</label><textarea name="address" class="form-control" required><?=e($_POST['address']??'')?></textarea><label class="form-label mt-3">City / District</label><input name="city" class="form-control" required value="<?=e($_POST['city']??'')?>"><h4 class="mt-4">Payment Method</h4><label class="d-block my-2"><input type="radio" name="payment" value="cod" required> Cash on Delivery</label><label class="d-block my-2"><input type="radio" name="payment" value="bank"> Bank Transfer (manual confirmation)</label><p class="muted small">Card payment is not yet integrated. Do not enter card details.</p><button class="btn btn-gold w-100 mt-3">PLACE ORDER</button></form></div><div class="col-lg-5"><div class="filter-panel"><h4>Order Summary</h4><?php foreach($rows as $r):?><div class="d-flex justify-content-between my-3"><span><?=e($r['name'])?> × <?=$r['qty']?></span><span><?=money($r['price']*$r['qty'])?></span></div><?php endforeach;?><hr><div class="d-flex justify-content-between"><span>Delivery (demo flat rate)</span><span><?=money($delivery)?></span></div><div class="d-flex justify-content-between mt-3 fs-5"><b>Total</b><b class="text-gold"><?=money(cart_total()+$delivery)?></b></div></div></div></div></section><?php require 'includes/footer.php';?>